describe('Rate Limit Error Handling', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should display a rate-limit error after multiple submissions', () => {
        const formData = { name: 'John Doe', email: 'john@example.com' };

        for (let i = 0; i < 5; i++) {
            cy.get('input[name="name"]').type(formData.name);
            cy.get('input[name="email"]').type(formData.email);
            cy.get('button[type="submit"]').click();
        }

        cy.get('.error-message').should('be.visible')
            .and('contain', 'You have submitted the form too many times. Please try again later.');
    });

    it('should not display a rate-limit error if submitted within limits', () => {
        const formData = { name: 'Jane Doe', email: 'jane@example.com' };

        cy.get('input[name="name"]').type(formData.name);
        cy.get('input[name="email"]').type(formData.email);
        cy.get('button[type="submit"]').click();

        cy.get('.success-message').should('be.visible')
            .and('contain', 'Form submitted successfully!');
    });
});
